import { useState } from "react";

export function App() {
  const [name, setName] = useState("");
  const [status, setStatus] = useState("idle");
  function submit(event: React.FormEvent) {
    event.preventDefault();
    setStatus("idle");
  }
  return (
    <form onSubmit={submit}>
      <label>Name <input data-testid="profile-name" value={name} onChange={(event) => setName(event.target.value)} /></label>
      <button data-testid="submit-profile" type="submit">Save profile</button>
      <span data-testid="profile-status">{status}</span>
    </form>
  );
}

